ec848d13da","name":"南瓜鮮菇雞絲飯","new_slug":"pumpkin-mushroom-chicken-rice","old_slug":"prepmeal-batch4-22","is_public":true,"updated_at":"2026-11-13T10:22:24.113778+00:00","content_md5":"4da33aaf3774231a675e142056dbaa0a"},{"id":"a4165f61-26cc-417b-b5f7-39ca17f365f9","name":"日式海鮮炒麵（家常版）","new_slug":"seafood-yakisoba","old_slug":"prepmeal-batch4-23","is_public":true,"updated_at":"2026-11-13T10:22:24.113778+00:00","content_md5":"ea94a88185a524c2de92d3ca8f8e6731"},{"id":"43383349-c72f-4752-954d-03e1e86c6eaa","name":"日式醬香生菜豬肉卷","new_slug":"japanese-lettuce-pork-rolls","old_slug":"prepmeal-batch4-24","is_public":true,"updated_at":"2026-11-13T10:22:24.113778+00:00","content_md5":"f16771426e8be3ebfef8ec3dcba6ce18"},{"id":"fd63e73a-9b5e-4087-a7ba-399f4c7042c1","name":"蒜香南瓜炒蝦仁（家常版）","new_slug":"garlic-pumpkin-shrimp","old_slug":"prepmeal-batch4-25","is_public":true,"updated_at":"2026-11-13T10:22:24.113778+00:00","content_md5":"0738bce14f0929d8b54cba4a923e75f4"}]$rename_payload$::jsonb)
AS p(id uuid, name text, old_slug text, new_slug text, is_public boolean, updated_at timestamptz, content_md5 text);

DO $guards$
DECLARE old_count integer; new_count integer; affected integer;
BEGIN
  IF (SELECT count(*) FROM slug_rename_expected) <> 100
     OR (SELECT count(DISTINCT id) FROM slug_rename_expected) <> 100
     OR (SELECT count(DISTINCT old_slug) FROM slug_rename_expected) <> 100
     OR (SELECT count(DISTINCT new_slug) FROM slug_rename_expected) <> 100 THEN
    RAISE EXCEPTION 'Expected exactly 100 unique recipe IDs and old/new slugs';
  END IF;
  IF EXISTS (SELECT 1 FROM slug_rename_expected WHERE new_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' OR old_slug = new_slug)
     OR EXISTS (SELECT 1 FROM slug_rename_expected a JOIN slug_rename_expected b ON a.new_slug=b.old_slug) THEN
    RAISE EXCEPTION 'Unsafe target slug or redirect chain';
  END IF;
  IF (SELECT count(*) FROM public.recipes r JOIN slug_rename_expected p ON r.id=p.id) <> 100
     OR EXISTS (SELECT 1 FROM public.recipes r JOIN slug_rename_expected p ON r.id=p.id
                WHERE r.is_public IS DISTINCT FROM true OR r.name IS DISTINCT FROM p.name
                   OR md5((to_jsonb(r)-'slug'-'updated_at'-'times_shown')::text) IS DISTINCT FROM p.content_md5) THEN
    RAISE EXCEPTION 'Recipe identity, visibility or reviewed content changed';
  END IF;
  IF EXISTS (SELECT 1 FROM public.recipes r JOIN slug_rename_expected p ON r.slug=p.new_slug WHERE r.id<>p.id) THEN
    RAISE EXCEPTION 'Target occupied by another recipe, including private rows';
  END IF;
  SELECT count(*) INTO old_count FROM public.recipes r JOIN slug_rename_expected p ON r.id=p.id AND r.slug=p.old_slug;
  SELECT count(*) INTO new_count FROM public.recipes r JOIN slug_rename_expected p ON r.id=p.id AND r.slug=p.new_slug;
  IF new_count=100 AND old_count=0 THEN
    RAISE NOTICE 'All 100 recipe slugs already renamed; no changes';
    RETURN;
  END IF;
  IF old_count<>100 OR new_count<>0 THEN
    RAISE EXCEPTION 'Unexpected or partial rename state: old %, new %',old_count,new_count;
  END IF;

  CREATE TEMP TABLE slug_rename_before ON COMMIT DROP AS
    SELECT r.id, to_jsonb(r)-'slug'-'updated_at' AS unchanged
    FROM public.recipes r JOIN slug_rename_expected p ON r.id=p.id;
  UPDATE public.recipes r SET slug=p.new_slug
    FROM slug_rename_expected p WHERE r.id=p.id AND r.slug=p.old_slug;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected<>100 THEN RAISE EXCEPTION 'Expected 100 updated recipes, found %',affected; END IF;
  -- ROW_COUNT alone does not prove that AFTER UPDATE triggers kept every row.
  SELECT count(*) INTO new_count FROM slug_rename_expected p JOIN public.recipes r ON r.id=p.id AND r.slug=p.new_slug;
  IF new_count<>100 OR EXISTS (
       SELECT 1 FROM slug_rename_expected p
       LEFT JOIN public.recipes r ON r.id=p.id
       LEFT JOIN slug_rename_before b ON b.id=p.id
       WHERE r.id IS NULL OR b.id IS NULL OR r.slug IS DISTINCT FROM p.new_slug
          OR to_jsonb(r)-'slug'-'updated_at' IS DISTINCT FROM b.unchanged) THEN
    RAISE EXCEPTION 'Post-update validation failed; transaction must roll back';
  END IF;
END;
$guards$;
SELECT count(*) AS renamed_rows FROM public.recipes r JOIN slug_rename_expected p ON r.id=p.id AND r.slug=p.new_slug;
COMMIT;
